{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance annual rent cap","requirement":"A landlord may not raise residential rent by more than the lower of 3% per year or 80% of the percent change in the Consumer Price Index over the most recent 12 months; no increase is allowed if the CPI is negative.","key_value":"lower of 3% per year or 80% of CPI change over most recent 12 months","coverage_conditions":"Residential rental property in Santa Ana, but not buildings constructed after February 1, 1995, or mobile home spaces offered for rent after January 1, 1990.","applicability":{"built_on_or_before":"1995-02-01","built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":false,"other":"Mobile home spaces offered for rent after January 1, 1990 are excluded"},"exemptions":"Residential buildings constructed after February 1, 1995; mobile home spaces offered for rent after January 1, 1990. Owners may petition the City Manager for relief from the cap, decided within 60 days of a complete application.","penalty":null,"effective_date":"2021-11-19","citation":"Santa Ana Rent Stabilization Ordinance","quoted_span":"Increase in residential rents are limited to the lower of 3% per year, or 80% of the percent change in the Consumer Price Index over the most recent 12-month period. If the CPI is negative, no rent increase is permitted.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D085-01","doc_id":"D085","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana Just Cause Eviction Ordinance","requirement":"After 30 days an owner may not terminate a tenancy without just cause, stated in a written notice; for at-fault causes the tenant must first get notice of the violation and time to fix it.","key_value":"3 months' relocation assistance or waiver of rent for the final 3 months","coverage_conditions":"Residential tenancies in place after 30 days. Excludes housing produced in the last 15 years, deed-restricted affordable housing, hotel and transient occupancy, hospital and care facilities, dormitories and other shared living quarters.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"unspecified","min_units":null,"max_units":null,"owner_dependent":false,"other":"Excludes housing produced in the last 15 years"},"exemptions":"Housing produced in the last 15 years; deed-restricted affordable housing; hotel and transient occupancy; hospital and care facilities; dormitories; and other shared living quarters.","penalty":null,"effective_date":"2021-11-19","citation":"Santa Ana Just Cause Eviction Ordinance","quoted_span":"After 30 days, an owner shall not terminate a tenancy without just cause, which shall be stated in a written notice.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
